const r = await api.get('/customers', {});
const items = r.items;
let count = 0;
for (const c of items) {
  if (c.birth_date) {
    // assume format YYYY-MM-DD or similar
    const month = new Date(c.birth_date).getMonth() + 1; // 1-indexed
    if (month === 11) count++;
  }
}
return {count};

